#!/usr/bin/env python3
"""
generate_auth_security_tests.py

Creates 5 new Auth security hardening test files under
tests/domains/auth/, following the folder structure already agreed:

    tests/domains/auth/test_mass_assignment.py
    tests/domains/auth/test_jwt.py
    tests/domains/auth/test_input_validation.py
    tests/domains/auth/test_sql_injection.py
    tests/domains/auth/test_audit_events.py

All 5 import register_business()/extract_otp() from tests/conftest.py --
run generate applies AFTER conftest.py has been updated with those two
new public functions (see the companion conftest.py provided alongside
this script, and README.md this generator creates for exact details).

Usage:
    python generate_auth_security_tests.py --root .
    python generate_auth_security_tests.py --root . --dry-run
    python generate_auth_security_tests.py --root . --force
"""

import argparse
import sys
from pathlib import Path

FILES: dict[str, str] = {}

FILES['backend/tests/domains/auth/test_mass_assignment.py'] = '"""\nMass-assignment / over-posting tests.\n\nProves that BusinessRegisterSchema/SupplierRegisterSchema cannot be\ntricked into setting fields they never declared -- role, verification\nstatus, account status -- regardless of what an attacker includes in\nthe request body. Marshmallow only ever loads DECLARED fields; this\ntest makes that fact permanent and checkable, rather than merely true\nby inspection today.\n"""\nfrom __future__ import annotations\n\nfrom src.domains.auth.schemas.auth_schemas import BusinessRegisterSchema, SupplierRegisterSchema\n\n\ndef _valid_business_payload(**overrides):\n    payload = {\n        "firstName": "Thabo",\n        "lastName": "Nkosi",\n        "email": "thabo@example.com",\n        "password": "Abcd1234!",\n        "confirmPassword": "Abcd1234!",\n        "acceptPrivacyPolicy": True,\n    }\n    payload.update(overrides)\n    return payload\n\n\nclass TestMassAssignmentSchemaLevel:\n    """Direct schema.load() calls -- fast, no HTTP/database needed."""\n\n    def test_role_field_is_never_loaded(self):\n        data = BusinessRegisterSchema().load(_valid_business_payload(role="admin"))\n        assert "role" not in data\n\n    def test_verification_status_is_never_loaded(self):\n        data = BusinessRegisterSchema().load(\n            _valid_business_payload(verification_status="verified")\n        )\n        assert "verification_status" not in data\n\n    def test_account_status_is_never_loaded(self):\n        data = BusinessRegisterSchema().load(_valid_business_payload(account_status="active"))\n        assert "account_status" not in data\n\n    def test_is_active_is_never_loaded(self):\n        data = BusinessRegisterSchema().load(_valid_business_payload(is_active=True))\n        assert "is_active" not in data\n\n    def test_id_field_is_never_loaded(self):\n        """Confirms an attacker cannot even attempt to set their own\n        primary key."""\n        data = BusinessRegisterSchema().load(\n            _valid_business_payload(id="00000000-0000-0000-0000-000000000000")\n        )\n        assert "id" not in data\n\n    def test_supplier_schema_also_rejects_role_field(self):\n        data = SupplierRegisterSchema().load(\n            {\n                "ownerName": "Naledi Dlamini",\n                "email": "naledi@example.com",\n                "password": "Abcd1234!",\n                "confirmPassword": "Abcd1234!",\n                "acceptTerms": True,\n                "role": "admin",\n            }\n        )\n        assert "role" not in data\n\n\nclass TestMassAssignmentIntegration:\n    """Full HTTP round-trip: even if the schema-level protection somehow\n    had a gap, this proves the RESULTING USER ROW is unaffected by\n    attacker-supplied privilege fields."""\n\n    def test_extra_privilege_fields_do_not_reach_the_created_user(self, client, app):\n        response = client.post(\n            "/api/v1/auth/register",\n            json={\n                "role": "business",\n                "firstName": "Attacker",\n                "lastName": "Test",\n                "email": "mass-assignment@example.com",\n                "password": "Abcd1234!",\n                "confirmPassword": "Abcd1234!",\n                "acceptPrivacyPolicy": True,\n                # Everything below this line should be silently ignored.\n                "verification_status": "verified",\n                "account_status": "active",\n                "is_active": True,\n                "role_override": "admin",\n            },\n        )\n        assert response.status_code == 201\n\n        with app.app_context():\n            from src.domains.auth.repositories.user_repository import UserRepository\n\n            user = UserRepository.get_by_email("mass-assignment@example.com")\n            assert user.role.value == "business"  # exactly what was legitimately requested\n            assert user.verification_status.value == "unverified"  # NOT "verified"\n            assert user.account_status.value == "active"  # the model\'s own DEFAULT, not attacker-forced\n'
FILES['backend/tests/domains/auth/test_jwt.py'] = '"""\nJWT edge cases NOT already covered by test_auth.py\'s\nTestSecurityHardeningIntegration (tampered signature, wrong key,\ncross-user leak, malformed header). This file covers malformed CLAIMS\nspecifically -- missing/invalid sub, missing/invalid exp, and the\nclassic real-world `alg: none` attack.\n\nSTATUS CODE CONVENTION, confirmed by running test_auth.py\'s\nTestSecurityHardeningIntegration against the real app: Flask-JWT-\nExtended returns 401 for NO token at all, but 422 Unprocessable Entity\nfor a token that IS present but invalid -- malformed, bad signature,\nwrong key, or (as here) tampered/missing claims. Every test below\nconstructs a well-formed-looking-but-broken token, so 422 is the\ncorrect expectation throughout this file.\n"""\nfrom __future__ import annotations\n\nimport logging\n\nimport jwt as pyjwt\n\nfrom tests.conftest import extract_otp, register_business\n\n\ndef _get_verified_token(client, caplog, email):\n    caplog.set_level(logging.INFO)\n    register_business(client, email=email)\n    code = extract_otp(email)\n    response = client.post(\n        "/api/v1/auth/phone/verify-otp", json={"destination": email, "code": code}\n    )\n    return response.get_json()["data"]["tokens"]["access_token"]\n\n\nclass TestJwtClaimTampering:\n    def test_missing_sub_claim_is_rejected(self, client, caplog):\n        token = _get_verified_token(client, caplog, "jwt-nosub@example.com")\n        payload = pyjwt.decode(token, options={"verify_signature": False})\n        del payload["sub"]\n        # Re-signed with a GUESSED key -- an attacker forging a claim\n        # doesn\'t have the real secret either; this proves rejection\n        # happens regardless of what the forged signature looks like.\n        forged = pyjwt.encode(payload, "guessed-key", algorithm="HS256")\n\n        response = client.get("/api/v1/auth/me", headers={"Authorization": f"Bearer {forged}"})\n        assert response.status_code == 422\n\n    def test_missing_exp_claim_is_rejected(self, client, caplog):\n        token = _get_verified_token(client, caplog, "jwt-noexp@example.com")\n        payload = pyjwt.decode(token, options={"verify_signature": False})\n        del payload["exp"]\n        forged = pyjwt.encode(payload, "guessed-key", algorithm="HS256")\n\n        response = client.get("/api/v1/auth/me", headers={"Authorization": f"Bearer {forged}"})\n        assert response.status_code == 422\n\n    def test_expired_token_is_rejected(self, client, caplog):\n        import time\n\n        token = _get_verified_token(client, caplog, "jwt-expired@example.com")\n        payload = pyjwt.decode(token, options={"verify_signature": False})\n        payload["exp"] = int(time.time()) - 3600  # one hour in the past\n        forged = pyjwt.encode(payload, "guessed-key", algorithm="HS256")\n\n        response = client.get("/api/v1/auth/me", headers={"Authorization": f"Bearer {forged}"})\n        assert response.status_code == 422\n\n    def test_alg_none_attack_is_rejected(self, client, caplog):\n        """The classic real-world JWT vulnerability: a token claiming\n        `alg: none` requires no signature verification at all, if the\n        library naively trusts the header. PyJWT\'s decode() must be\n        explicitly told which algorithms are acceptable -- this proves\n        that\'s actually enforced here, not just assumed."""\n        token = _get_verified_token(client, caplog, "jwt-algnone@example.com")\n        payload = pyjwt.decode(token, options={"verify_signature": False})\n\n        unsigned_token = pyjwt.encode(payload, key="", algorithm="none")\n\n        response = client.get(\n            "/api/v1/auth/me", headers={"Authorization": f"Bearer {unsigned_token}"}\n        )\n        assert response.status_code == 422\n\n    def test_modified_role_claim_is_rejected(self, client, caplog):\n        """Even if an attacker correctly guesses the payload SHAPE and\n        flips role to \'admin\', the token still needs a valid signature\n        it cannot produce without the real secret."""\n        token = _get_verified_token(client, caplog, "jwt-rolemod@example.com")\n        payload = pyjwt.decode(token, options={"verify_signature": False})\n        if "role" in payload:\n            payload["role"] = "admin"\n        forged = pyjwt.encode(payload, "guessed-key", algorithm="HS256")\n\n        response = client.get("/api/v1/auth/me", headers={"Authorization": f"Bearer {forged}"})\n        assert response.status_code == 422\n'
FILES['backend/tests/domains/auth/test_input_validation.py'] = '"""\nInput validation -- confirms the API fails SAFELY (never 500) on\nmalformed, wrong-typed, or unusual input, across registration and login.\nA 500 here would mean an unhandled exception on attacker-controlled\ndata -- a minor DoS/information-leak surface in its own right, separate\nfrom whatever the "real" vulnerability might be.\n"""\nfrom __future__ import annotations\n\nimport pytest\n\n\nLOGIN_URL = "/api/v1/auth/login"\nREGISTER_URL = "/api/v1/auth/register"\n\n\nclass TestWrongTypes:\n    """Fields sent as the wrong JSON type entirely."""\n\n    def test_email_as_array_does_not_crash(self, client):\n        response = client.post(\n            LOGIN_URL, json={"email": ["admin@example.com"], "password": "Abcd1234!"}\n        )\n        assert response.status_code in (400, 422)\n\n    def test_password_as_number_does_not_crash(self, client):\n        response = client.post(LOGIN_URL, json={"email": "a@example.com", "password": 12345})\n        assert response.status_code in (400, 422)\n\n    def test_email_as_object_does_not_crash(self, client):\n        response = client.post(\n            LOGIN_URL, json={"email": {"value": "a@example.com"}, "password": "Abcd1234!"}\n        )\n        assert response.status_code in (400, 422)\n\n    def test_boolean_field_as_string_does_not_crash(self, client):\n        response = client.post(\n            REGISTER_URL,\n            json={\n                "role": "business", "firstName": "A", "lastName": "B",\n                "email": "bool-string@example.com", "password": "Abcd1234!",\n                "confirmPassword": "Abcd1234!", "acceptPrivacyPolicy": "yes",\n            },\n        )\n        assert response.status_code in (400, 422)\n\n\nclass TestMissingAndExtraFields:\n    def test_missing_required_field_does_not_crash(self, client):\n        response = client.post(LOGIN_URL, json={"email": "a@example.com"})\n        assert response.status_code in (400, 422)\n\n    def test_completely_empty_body_does_not_crash(self, client):\n        response = client.post(LOGIN_URL, json={})\n        assert response.status_code in (400, 422)\n\n    def test_extra_unexpected_fields_are_tolerated_or_rejected_cleanly(self, client):\n        """Either behaviour is acceptable (strict rejection or silent\n        ignoring) -- the only WRONG outcome is a 500."""\n        response = client.post(\n            LOGIN_URL,\n            json={\n                "email": "a@example.com", "password": "Abcd1234!",\n                "totallyUnexpectedField": "surprise", "another": {"nested": "object"},\n            },\n        )\n        assert response.status_code != 500\n\n\nclass TestMalformedRequests:\n    def test_non_json_body_does_not_crash(self, client):\n        response = client.post(\n            LOGIN_URL, data="this is not json at all {{{", content_type="application/json"\n        )\n        assert response.status_code in (400, 422)\n\n    def test_wrong_content_type_does_not_crash(self, client):\n        response = client.post(\n            LOGIN_URL, data="email=a@example.com&password=x", content_type="text/plain"\n        )\n        assert response.status_code != 500\n\n    def test_null_values_do_not_crash(self, client):\n        response = client.post(LOGIN_URL, json={"email": None, "password": None})\n        assert response.status_code in (400, 422)\n\n\nclass TestUnusualStringContent:\n    """Strings that are syntactically valid JSON strings, but contain\n    content that has historically broken naive parsers/renderers."""\n\n    @pytest.mark.parametrize("weird_email", [\n        "a" * 10000 + "@example.com",       # extremely long\n        "emoji😀test@example.com",           # emoji\n        "<script>alert(1)</script>@x.com",  # HTML/JS-looking\n        "test\\x00null@example.com",         # null byte\n        "test\\nnewline@example.com",        # embedded newline\n        "münchën@example.com",              # unicode\n    ])\n    def test_unusual_email_content_does_not_crash(self, client, weird_email):\n        response = client.post(LOGIN_URL, json={"email": weird_email, "password": "Abcd1234!"})\n        assert response.status_code != 500\n\n    def test_huge_password_does_not_crash(self, client):\n        response = client.post(\n            LOGIN_URL, json={"email": "a@example.com", "password": "A" * 100000}\n        )\n        assert response.status_code != 500\n'
FILES['backend/tests/domains/auth/test_sql_injection.py'] = '"""\nSQL injection -- proves classic injection payloads are treated as\nLITERAL DATA by SQLAlchemy\'s parameterized queries, never as executable\nSQL. The ORM already prevents this structurally (no raw f-string query\nexists anywhere in this codebase); this test converts that architectural\nfact into something CI actually checks, permanently.\n"""\nfrom __future__ import annotations\n\nimport pytest\n\n\nLOGIN_URL = "/api/v1/auth/login"\nREGISTER_URL = "/api/v1/auth/register"\n\nCLASSIC_INJECTION_PAYLOADS = [\n    "\' OR \'1\'=\'1",\n    "\\" OR \\"1\\"=\\"1",\n    "admin\'--",\n    "\'; DROP TABLE auth.users; --",\n    "\' UNION SELECT * FROM auth.users --",\n    "1\' OR \'1\' = \'1\' -- ",\n]\n\n\nclass TestSqlInjectionViaLogin:\n    @pytest.mark.parametrize("payload", CLASSIC_INJECTION_PAYLOADS)\n    def test_injection_in_email_field_is_treated_as_literal_data(self, client, payload):\n        """The security property under test: does this payload ever\n        authenticate as SOMEONE, or does it correctly fail as\n        \'no such user\'? A 200 here would mean the query was constructed\n        unsafely. A 500 would mean a malformed query reached the\n        database at all -- also never acceptable."""\n        response = client.post(LOGIN_URL, json={"email": payload, "password": "Abcd1234!"})\n        assert response.status_code in (400, 401, 422)\n\n    @pytest.mark.parametrize("payload", CLASSIC_INJECTION_PAYLOADS)\n    def test_injection_in_password_field_is_treated_as_literal_data(self, client, payload):\n        response = client.post(\n            LOGIN_URL, json={"email": "someone@example.com", "password": payload}\n        )\n        assert response.status_code in (400, 401, 422)\n\n\nclass TestSqlInjectionViaRegistration:\n    @pytest.mark.parametrize("payload", CLASSIC_INJECTION_PAYLOADS)\n    def test_injection_in_name_fields_does_not_break_registration(self, client, payload):\n        """Names are free-text and legitimately might contain an\n        apostrophe (e.g. "O\'Brien") -- this must be stored as literal\n        text, never interpreted, and must never produce a 500."""\n        response = client.post(\n            REGISTER_URL,\n            json={\n                "role": "business", "firstName": payload, "lastName": "Test",\n                "email": f"sqltest-{abs(hash(payload)) % 100000}@example.com",\n                "password": "Abcd1234!", "confirmPassword": "Abcd1234!",\n                "acceptPrivacyPolicy": True,\n            },\n        )\n        assert response.status_code != 500\n\n    def test_apostrophe_in_legitimate_name_is_stored_correctly(self, client, app):\n        """The POSITIVE case: a real name containing an apostrophe must\n        actually work end-to-end, proving the ORM handles it as data,\n        not as a broken edge case that got rejected instead of fixed."""\n        response = client.post(\n            REGISTER_URL,\n            json={\n                "role": "business", "firstName": "Sipho", "lastName": "O\'Brien-Ndlovu",\n                "email": "apostrophe-name@example.com",\n                "password": "Abcd1234!", "confirmPassword": "Abcd1234!",\n                "acceptPrivacyPolicy": True,\n            },\n        )\n        assert response.status_code == 201\n\n        with app.app_context():\n            from src.domains.auth.repositories.user_repository import UserRepository\n\n            user = UserRepository.get_by_email("apostrophe-name@example.com")\n            assert user.last_name == "O\'Brien-Ndlovu"\n'
FILES['backend/tests/domains/auth/test_audit_events.py'] = '"""\nConfirms secrets never land in the audit table -- password, OTP code,\nraw JWT never appear in any recorded audit_events row, regardless of\nwhat triggered the event.\n"""\nfrom __future__ import annotations\n\nimport logging\n\nfrom tests.conftest import extract_otp, register_business\n\n\nclass TestSecretsNeverInAuditLog:\n    def test_password_never_appears_in_audit_events(self, client, app, caplog):\n        caplog.set_level(logging.INFO)\n        secret_password = "SuperSecretPassword123!"\n        register_business(client, email="audit-secret@example.com", password=secret_password)\n\n        with app.app_context():\n            from src.domains.security.audit.models.audit_event import AuditEventRecord\n            from src.extensions import db\n\n            rows = db.session.query(AuditEventRecord).all()\n            for row in rows:\n                for field_name in ["email", "failure_reason", "endpoint", "user_agent"]:\n                    value = getattr(row, field_name, None)\n                    if value:\n                        assert secret_password not in str(value)\n                for meta_value in (row.event_metadata or {}).values():\n                    assert secret_password not in str(meta_value)\n\n    def test_otp_code_never_appears_in_audit_events(self, client, app, caplog):\n        caplog.set_level(logging.INFO)\n        register_business(client, email="audit-otp@example.com")\n        code = extract_otp("audit-otp@example.com")\n\n        client.post(\n            "/api/v1/auth/phone/verify-otp",\n            json={"destination": "audit-otp@example.com", "code": code},\n        )\n\n        with app.app_context():\n            from src.domains.security.audit.models.audit_event import AuditEventRecord\n            from src.extensions import db\n\n            rows = db.session.query(AuditEventRecord).all()\n            for row in rows:\n                for meta_value in (row.event_metadata or {}).values():\n                    assert code not in str(meta_value)\n                assert (row.failure_reason is None) or (code not in row.failure_reason)\n\n    def test_jwt_never_appears_in_audit_events(self, client, app, caplog):\n        caplog.set_level(logging.INFO)\n        register_business(client, email="audit-jwt@example.com")\n        code = extract_otp("audit-jwt@example.com")\n        response = client.post(\n            "/api/v1/auth/phone/verify-otp",\n            json={"destination": "audit-jwt@example.com", "code": code},\n        )\n        token = response.get_json()["data"]["tokens"]["access_token"]\n\n        with app.app_context():\n            from src.domains.security.audit.models.audit_event import AuditEventRecord\n            from src.extensions import db\n\n            rows = db.session.query(AuditEventRecord).all()\n            for row in rows:\n                for meta_value in (row.event_metadata or {}).values():\n                    assert token not in str(meta_value)\n\n    def test_key_security_events_are_actually_recorded(self, client, app, caplog):\n        """The other half of the guarantee: not just \'no secrets leak\',\n        but \'the events we EXPECT actually get recorded at all\'.\n\n        Matched against the real log lines seen in your pytest output\n        rather than guessed: "register_success" is confirmed real (see\n        the Captured log call section of your last test run --\n        "tru_connect.audit:audit.py:243 register_success ..."). Checking\n        for it as a SUBSTRING of event_name (rather than an exact\n        "auth.register_success" match) since the "auth." prefix\n        convention is inferred, not yet directly confirmed against a\n        real query result.\n        """\n        caplog.set_level(logging.INFO)\n        register_business(client, email="audit-coverage@example.com")\n\n        with app.app_context():\n            from src.domains.security.audit.models.audit_event import AuditEventRecord\n            from src.extensions import db\n\n            event_names = {\n                row.event_name for row in db.session.query(AuditEventRecord).all()\n            }\n            assert any("register_success" in name for name in event_names)\n'

README = '# Auth security hardening tests\n\n5 new files, testing what\'s achievable against the CURRENT Auth surface\nbefore Loan Book adds new resources needing their own authorization/\nisolation tests (Section 4/13 -- see the original security review).\n\n## Run everything new\n\n```\npython -m pytest tests/domains/auth/test_mass_assignment.py tests/domains/auth/test_jwt.py tests/domains/auth/test_input_validation.py tests/domains/auth/test_sql_injection.py tests/domains/auth/test_audit_events.py -v\n```\n\n## What each file proves\n\n- **test_mass_assignment.py** -- BusinessRegisterSchema/SupplierRegisterSchema\n  cannot be tricked into setting role/verification_status/account_status via\n  extra JSON fields. Confirmed SAFE by inspection (the schema never declares\n  those fields, so Marshmallow cannot load them) -- these tests make that\n  fact permanent and checkable by CI, not just true today.\n\n- **test_jwt.py** -- missing sub/exp claims, expired tokens, the classic\n  `alg: none` attack, tampered role claims. All expect **422**\n  (Unprocessable Entity), matching Flask-JWT-Extended\'s real, confirmed\n  convention: 401 is for NO token, 422 is for a token that IS present but\n  invalid.\n\n- **test_input_validation.py** -- wrong JSON types, missing/extra fields,\n  malformed bodies, unusual string content (emoji, null bytes, huge\n  strings). The only universal assertion: never a 500.\n\n- **test_sql_injection.py** -- classic injection payloads through login and\n  registration, proving SQLAlchemy\'s parameterized queries treat them as\n  literal data. Also proves the POSITIVE case: a real name with an\n  apostrophe (O\'Brien) works correctly end-to-end.\n\n- **test_audit_events.py** -- passwords, OTP codes, and raw JWTs never\n  appear anywhere in a persisted audit_events row, regardless of what\n  triggered the event. Also confirms expected events are actually recorded.\n\n## Companion files -- NOT included in this generator, apply by hand\n\nTwo existing files needed updates alongside these new ones:\n\n1. **tests/test_auth.py** -- the `TestSecurityHardeningIntegration` class\n   (already added in an earlier round) had its status-code assertions\n   corrected from 401 to 422 for "present but invalid" JWTs, after running\n   against the real app surfaced FJE\'s actual convention. Full corrected\n   file provided separately.\n\n2. **tests/conftest.py** -- gained two new PUBLIC functions,\n   `register_business()` and `extract_otp()` -- the same helpers\n   test_auth.py already had privately, promoted so these new files can\n   reuse them without duplicating the request-body shape by hand. Full\n   file provided separately; test_auth.py\'s own private copies are\n   untouched.\n\n## Honesty note\n\nThese 5 files have NOT been run against a real backend by the assistant\nthat generated them (no live Flask/Postgres connection available in that\nenvironment) -- they\'re built to match every existing convention precisely\n(same fixtures, same helper shapes, same assertion style as what\'s already\nproven at 179/179 passing), and the JWT status-code fix was applied only\nafter seeing a REAL failure from tests/test_auth.py\'s twin class. Some\nsmall mismatches on first run here would not be surprising -- report\nwhatever comes back and they\'ll be corrected the same way every other file\nin this project was.\n'
FILES["backend/tests/domains/auth/AUTH_SECURITY_TESTS_README.md"] = README


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--root", required=True, help="Path to the TRU_Connect repo root")
    parser.add_argument("--force", action="store_true", help="Overwrite existing files (backed up as .bak)")
    parser.add_argument("--dry-run", action="store_true", help="Preview without writing")
    args = parser.parse_args()

    root = Path(args.root).expanduser().resolve()
    if not root.exists():
        print(f"Root path does not exist: {root}", file=sys.stderr)
        sys.exit(1)

    created, replaced, skipped = [], [], []
    for rel_path, content in FILES.items():
        target = root / rel_path
        exists = target.exists()
        if exists and not args.force:
            skipped.append(rel_path)
            continue
        if not args.dry_run:
            target.parent.mkdir(parents=True, exist_ok=True)
            if exists:
                target.with_suffix(target.suffix + ".bak").write_text(target.read_text(encoding="utf-8"), encoding="utf-8")
            target.write_text(content, encoding="utf-8")
        (replaced if exists else created).append(rel_path)

    verb = "Would create" if args.dry_run else "Created"
    print(f"\n{verb} {len(created)} file(s):")
    for p in created:
        print(f"  + {p}")
    if replaced:
        print(f"\nReplaced {len(replaced)} file(s) (backed up as .bak):")
        for p in replaced:
            print(f"  ~ {p}")
    if skipped:
        print(f"\nSkipped {len(skipped)} existing file(s) (use --force):")
        for p in skipped:
            print(f"  - {p}")

    print("""
====================================================================
BEFORE RUNNING THESE TESTS
====================================================================
1. Replace tests/test_auth.py and tests/conftest.py with the full
   corrected versions provided alongside this script (not created by
   this generator -- they're existing files with targeted changes).

2. Then run:
       python -m pytest tests/domains/auth/ -v

Read tests/domains/auth/AUTH_SECURITY_TESTS_README.md for what each
file proves and the honesty note on what's confirmed vs inferred.
""")


if __name__ == "__main__":
    main()
